const V = [
 {id:"lft", c:"tests", t:"Liver Function Test (LFT)", l:"Hindi", d:"2:21",
  s:"Dr. Health fights Fatty Liver, Hepatitis and Alcohol with the LFT blood test.",
  x:[["What it checks","SGPT and SGOT (liver damage alarm), bilirubin (jaundice), albumin (liver strength), ALP (bile flow)."],
     ["Who should test","People who drink alcohol regularly, are overweight or diabetic, take long-term medicines, or have had jaundice or hepatitis."],
     ["Approximate normal","SGPT/SGOT up to about 40 U/L · Bilirubin 0.3–1.2 mg/dL · Albumin 3.5–5.0 g/dL"],
     ["Good to know","Early fatty liver can often be reversed with diet and exercise. Your liver can regrow itself."]]},
 {id:"lipid", c:"tests", t:"Lipid Profile", l:"Hindi", d:"2:16",
  s:"Your heart against Bad Cholesterol, Smoking and Junk Food. High cholesterol has no symptoms.",
  x:[["What it checks","Total cholesterol, LDL (bad), HDL (good) and triglycerides."],
     ["Who should test","Every adult from age 20, yearly after 40; people with diabetes, high BP, smoking, extra weight, or early heart attack in the family."],
     ["Preparation","Fast for 10–12 hours. Water is fine. Follow your lab's instructions."],
     ["Healthy levels (mg/dL)","Total below 200 · LDL below 100 · Triglycerides below 150 · HDL above 40 (men) / 50 (women)"]]},
 {id:"cbc", c:"tests", t:"CBC (Complete Blood Count)", l:"Hindi", d:"2:21",
  s:"The blood team of red cells, white cells and platelets fights Anaemia, Infection and Dengue.",
  x:[["What it checks","Haemoglobin and RBC (anaemia), WBC (infection), platelets (dengue and bleeding)."],
     ["Who should test","Tiredness or pale skin, fever for 2 days or more, pregnancy, and a yearly check-up."],
     ["Preparation","No fasting needed."],
     ["Approximate normal","Hb men 13–17 / women 12–15 g/dL · WBC 4,000–11,000 /cumm · Platelets 1.5–4.5 lakh /cumm"]]},
 {id:"kft", c:"tests", t:"Kidney Function Test (KFT)", l:"Hindi", d:"2:25",
  s:"Kidneys can fail silently. The kidney hero takes on Diabetes, High BP and painkiller overuse.",
  x:[["What it checks","Creatinine (filter alarm), urea (waste level), eGFR (filter speed), uric acid and salts."],
     ["Who should test","Diabetes or high BP, long-term painkiller use, swelling in feet or face, foamy urine, kidney disease in the family."],
     ["Approximate normal","Creatinine men 0.7–1.3 / women 0.6–1.1 mg/dL · Urea 15–40 mg/dL · eGFR 90 or above"],
     ["Good to know","Usually no fasting needed. Never take painkillers without a doctor's advice."]]},
 {id:"usg", c:"tests", t:"Whole Abdomen USG", l:"Hindi", d:"2:32",
  s:"An ultrasound uses sound waves to find Gallstones, Fatty Liver and Kidney Stones. No radiation, no pain.",
  x:[["What it shows","Liver and gallbladder, kidneys and bladder, pancreas and spleen, uterus and ovaries or prostate."],
     ["Preparation","Fast 6–8 hours. Drink 4–5 glasses of water an hour before and hold urine so the bladder stays full."],
     ["Report words","Calculus = stone · Cholelithiasis = gallbladder stones · Hepatomegaly = enlarged liver · Simple cyst = fluid bubble, often harmless"],
     ["Good to know","Painless, safe in pregnancy, and usually takes 15–20 minutes."]]},
 {id:"echo", c:"tests", t:"2D Echo (Echocardiography)", l:"Hindi", d:"2:37",
  s:"An ultrasound of the heart that checks its size, pumping power and valves.",
  x:[["What it shows","Heart size and wall thickness, pumping power (EF), valves (open, close or leak), holes and fluid around the heart."],
     ["When it's advised","Breathlessness, chest pain, swelling in the feet, a heart murmur, or long-standing high BP or diabetes."],
     ["Report words","EF 55–70% = normal pumping · LVH = thick heart wall · MR/TR/AR = leaky valve · Stenosis = narrow valve"],
     ["ECG vs Echo","ECG checks the heart's electrical rhythm. Echo shows moving pictures of its structure."]]},
 {id:"urine", c:"tests", t:"Urine Routine (R/E)", l:"Hindi", d:"2:25",
  s:"A small sample with a big report card, plus the urine colour chart.",
  x:[["What it checks","Colour and clarity, sugar and protein, pus cells and bacteria (infection), blood and crystals (stone clues)."],
     ["How to give the sample","First morning urine, clean the area, skip the first few drops, use the lab's sterile cup, and deliver within an hour."],
     ["Usually normal","Sugar nil · Protein nil or trace · Pus cells 0–5 /hpf · RBC 0–2 /hpf"],
     ["Colour guide","Pale yellow = well hydrated · Dark yellow = drink more water · Red or brown = see a doctor"]]},
 {id:"culture", c:"tests", t:"Urine Culture & Sensitivity", l:"Hindi", d:"2:35",
  s:"Finds the exact germ behind a UTI and which antibiotic will actually work.",
  x:[["What it does","Grows germs from urine on a lab plate for 48–72 hours, then tests antibiotics against them."],
     ["When it's advised","Repeated UTI, no improvement with medicine, fever with burning urine, pregnancy, children and catheter patients."],
     ["Report words","No growth = usually no infection · More than 1 lakh CFU/mL = significant · S = antibiotic works · R = it won't"],
     ["Most important tip","Give the sample before starting antibiotics. Never take antibiotics without a doctor."]]},
 {id:"hba1c", c:"tests", t:"HbA1c & Blood Sugar", l:"Bengali", d:"2:08",
  s:"Why your doctor asks for HbA1c even when the sugar test is normal.",
  x:[["What it checks","Your average blood sugar over the last 2–3 months."],
     ["Who should test","Everyone above 30 yearly; family history of diabetes, extra weight, high BP or PCOS; diabetics every 3 months."],
     ["Results","HbA1c below 5.7% normal · 5.7–6.4% prediabetes · 6.5% or above diabetes"],
     ["Good to know","No fasting needed for HbA1c. Anaemia or thalassaemia can make it misleading."]]},
 {id:"vitd", c:"tests", t:"Vitamin D & B12", l:"Bengali", d:"2:13",
  s:"Always tired, aching or tingling? It could be low Vitamin D or B12.",
  x:[["What it checks","Vitamin D for bones and muscles; Vitamin B12 for blood and nerves."],
     ["Who should test","People mostly indoors, women over 40 and the elderly, vegetarians, and long-term metformin or acidity-tablet users."],
     ["Approximate normal","Vitamin D 30–100 ng/mL · B12 above 300 pg/mL"],
     ["Good to know","Don't take high-dose Vitamin D on your own. Test first."]]},

 {id:"dmarker", c:"preg", t:"Double Marker Test", l:"Hindi", d:"2:11",
  s:"Part 1. A first-trimester blood test, and what 'high risk' really means.",
  x:[["What it is","A blood test (beta-hCG and PAPP-A) read together with the NT scan."],
     ["When","Between 11 and 14 weeks of pregnancy. If missed, triple or quad marker at 15–20 weeks."],
     ["What it screens for","The chance of Down syndrome (21), Edwards (18) and Patau (13)."],
     ["Remember","Screening is not diagnosis. Most high-risk results still have healthy babies. Baby's sex is never disclosed."]]},
 {id:"nipt", c:"preg", t:"NIPT", l:"Hindi", d:"2:26",
  s:"Part 2. Reads tiny pieces of the baby's DNA in the mother's blood.",
  x:[["What it is","Non-Invasive Prenatal Test: one blood sample from the mother. Safe for the baby."],
     ["When","From 10 weeks of pregnancy. Results usually in 1–2 weeks."],
     ["Accuracy","Detects over 99% of Down syndrome cases, but it is still a screening test."],
     ["Good to know","An anomaly scan is still needed. Costlier than double marker. Tell your doctor about twins or IVF."]]},
 {id:"cvs", c:"preg", t:"CVS & Amniocentesis", l:"Hindi", d:"2:29",
  s:"Part 3. Diagnostic tests that give a confirmed answer.",
  x:[["CVS","At 11–14 weeks. A tiny sample of placenta, taken under ultrasound."],
     ["Amniocentesis","From 15 weeks. 3–4 teaspoons of the fluid around the baby."],
     ["What they confirm","Chromosome conditions, thalassaemia major in the baby, and other genetic diseases."],
     ["Safety","Done by an expert in a few minutes. Small miscarriage risk, usually under 1%. Rh-negative mothers may need anti-D."]]},

 {id:"karyo", c:"gen", t:"Karyotyping", l:"Hindi", d:"2:42",
  s:"Counts all 46 chromosomes. Key test for repeated miscarriages and infertility.",
  x:[["What it checks","All 46 chromosomes (23 pairs): extra or missing chromosomes and swapped pieces (translocations)."],
     ["Who should test","Couples with 2 or more miscarriages, infertility or very low sperm count, a child with delay or birth defects, girls with short height and no periods, some blood cancers (bone marrow)."],
     ["Sample & time","Usually a blood sample; in pregnancy, a CVS or amniocentesis sample. Report in about 2–3 weeks."],
     ["Reading the report","46,XX = normal female · 46,XY = normal male · 47,XY,+21 = Down syndrome. The first number is the total count."],
     ["Good to know","Very small changes are missed; microarray or exome may be needed. Baby's sex is not disclosed in pregnancy."]]},
 {id:"cma", c:"gen", t:"Chromosomal Microarray: 750K vs 315K", l:"Hindi", d:"2:51",
  s:"Finds tiny missing or extra chromosome pieces that a karyotype cannot see.",
  x:[["What it checks","Small deletions (missing pieces) and duplications (extra pieces) across all chromosomes."],
     ["750K vs 315K","750K: about 7.5 lakh probes, finer detail, mostly for children and adults. 315K: about 3.15 lakh probes, focused on key regions, mostly for pregnancy (CVS/amnio) and miscarriage tissue."],
     ["Who should test","Developmental delay, autism, birth defects, a problem seen on the baby's scan, repeated miscarriage or stillbirth."],
     ["Why it matters","Finds a cause in about 15–20% of children with delay or autism, versus about 3–5% with karyotype."],
     ["Good to know","Does not show balanced translocations (karyotype) or single-letter changes (exome). Parents' samples may be needed."]]},
 {id:"wes", c:"gen", t:"Whole Exome Sequencing", l:"Hindi", d:"2:40",
  s:"Reads about 20,000 genes letter by letter when other tests give no answer.",
  x:[["What it checks","The exome: the 1–2% of DNA that holds the recipes for proteins, where most known disease-causing changes are found."],
     ["Who should test","Delayed development, unexplained fits or muscle weakness, multiple birth defects, unknown genetic illness in the family, or when other tests gave no answer."],
     ["Sample & time","Blood (or saliva). Report in about 3–6 weeks. Testing the child with both parents ('trio') gives more reliable results."],
     ["Reading the report","Positive (cause found) · Negative (no cause found, genetic not ruled out) · VUS (change of uncertain meaning). About 1 in 3 families find an answer."],
     ["Good to know","Cannot catch every change (e.g. Fragile X). Genetic counselling before and after is important."]]},

 {id:"amh", c:"preg", t:"AMH test (egg reserve)", l:"Hindi", d:"2:43",
  s:"Planning a baby and told to do AMH? What it shows, what it doesn't, and why low AMH is not 'no baby'.",
  x:[["What it is","Anti-Müllerian Hormone, made by small egg sacs in the ovaries. It shows roughly how many eggs are left (ovarian reserve). It falls with age, faster after 35."],
     ["What it does NOT show","Egg quality, or your chance of natural pregnancy. In a large study (JAMA 2017) of women 30–44, low AMH did not lower natural pregnancy chances."],
     ["When it is useful","IVF planning (how the ovaries may respond to medicines), PCOS (often high), egg freezing or planning a baby later, after ovary surgery or chemotherapy. As your doctor advises."],
     ["The test","One blood sample, any day of the cycle. Birth control pills can make AMH read lower; tell your doctor."],
     ["Reading the report","Low: fewer eggs left, see a fertility doctor. Normal for age: reassuring. High: sometimes seen in PCOS. Normal range depends on age and the lab; doctors also check age, ultrasound and other hormones. Both partners matter."]]},

 {id:"eeg", c:"tests", t:"EEG test (brain waves)", l:"Hindi", d:"2:40",
  s:"Fits, fainting or blank spells? What an EEG is, how to prepare, and why a normal EEG does not rule out epilepsy.",
  x:[["What it is","Electroencephalogram: small sensors on the scalp record the brain's electrical activity. Painless; no current goes into the body."],
     ["When it is done","Fits / seizures / epilepsy, fainting or unexplained spells, after a head injury, some sleep problems, very sick patients in ICU. As your doctor advises."],
     ["Preparation","Wash hair the night before or that day; no oil, gel or conditioner. Eat normally. Don't stop medicines on your own; take them as your doctor advises."],
     ["Sleep EEG","You may be asked to sleep less the night before. Don't drive afterwards and bring someone along."],
     ["During & report","Lie down, eyes closed; recording usually 20–40 minutes, with deep breathing or flashing light. A normal EEG does not rule out epilepsy; a repeat, sleep, long or video EEG may be needed. The doctor decides along with your symptoms."]]},

 {id:"sleep", c:"tests", t:"Sleep study (sleep apnoea)", l:"Hindi", d:"2:54",
  s:"Loud snoring and tired all day? Sleep apnoea signs, risks, the overnight sleep study (polysomnography) and what the AHI number means.",
  x:[["What it is","In obstructive sleep apnoea the throat closes again and again during sleep, so breathing stops for 10 seconds or more. A bed partner often notices it first. Not everyone who snores has it."],
     ["In India","An AIIMS New Delhi study (2023) estimated about 11% of Indian adults may have it, roughly 10 crore people; most don't know."],
     ["Signs & risk","Loud snoring, breathing pauses or choking sounds, morning headache, daytime sleepiness, poor focus. More likely with extra weight or a thick neck, older age, family history, alcohol or smoking, large tonsils, sleeping on the back."],
     ["The test","Sleep study (polysomnography): painless sensors record breathing, oxygen, heartbeat, brain waves and movement overnight. Some people can be tested at home; the doctor decides. Avoid tea, coffee and alcohol on the test day; sleeping pills only if your doctor says."],
     ["Report & treatment","AHI = breathing pauses per hour: below 5 normal, 5–14 mild, 15–29 moderate, 30+ severe. Treatable: weight loss, no alcohol or smoking, side sleeping, and a CPAP machine if the doctor advises."]]},

 {id:"emg", c:"tests", t:"EMG & NCV (nerve and muscle test)", l:"Hindi", d:"2:55",
  s:"Tingling, numbness or weak muscles? What EMG and NCV check, how they are done, preparation and what to tell your doctor.",
  x:[["What they are","EMG records the electrical activity of muscles. NCV (nerve conduction study) measures how fast and how strongly signals travel along a nerve. They are often done together, NCV first."],
     ["When advised","Tingling or numbness in hands, feet or face, muscle weakness, cramps, spasms or twitching, or paralysis. Helps find carpal tunnel syndrome, neuropathy (common in diabetes), a nerve pressed by a spine disc, myasthenia gravis and some muscle diseases."],
     ["How it is done","NCV: sticker electrodes and a very mild electric pulse, a quick tingle. Needle EMG: a very thin needle in the muscle while you relax and then gently tighten it; some pain that settles soon after. Tell the doctor if it hurts too much."],
     ["Preparation","Bathe before; no cream, lotion or oil on the skin; loose clothes; usually no fasting. Tell your doctor about a pacemaker or blood thinners. Never stop any medicine on your own."],
     ["Time & report","About 30 minutes to 1.5 hours, depending on how many nerves and muscles are tested. Mild soreness or a bruise for 1–2 days. A neurologist writes the report; your doctor explains it with your symptoms."]]},

 {id:"ncv", c:"tests", t:"NCV test (nerve conduction)", l:"Hindi", d:"2:51",
  s:"Burning or numb feet, tingling hands? How the NCV test measures nerve speed, what slows it, preparation and why a normal result is not the full story.",
  x:[["What it is","Nerve Conduction Velocity: sticker electrodes and a mild pulse measure how fast and how strongly signals travel along a nerve. Speed = distance between electrodes ÷ time taken."],
     ["What it shows","Damage to the nerve's inner wire (axon) makes the signal weak; damage to its cover (myelin) makes it slow; a pressed nerve can block it."],
     ["Helps find","Diabetic neuropathy, carpal tunnel syndrome, Bell's palsy, Guillain-Barré syndrome, nerve injury, a nerve pressed by a spine disc. As your doctor advises."],
     ["Preparation","No lotion, cream, oil, sunscreen or perfume that day; loose clothes; tell staff about a pacemaker. Keep hands and feet warm: a cold nerve conducts slower and can give a wrong result. Usually no needle (EMG uses one)."],
     ["Time & report","15 minutes to over an hour, depending on how many nerves are tested. Children have slower values, so results are read by age; normal ranges differ a little by lab. A normal NCV does not always mean no nerve damage; the doctor reads it with your symptoms."]]},

 {id:"sma", c:"gen", t:"SMA genetic test (SMN1 gene)", l:"Hindi", d:"3:22",
  s:"Baby not holding the head up or late to sit? What spinal muscular atrophy is, how carriers pass it on, and how the SMN1 gene test (MLPA) works.",
  x:[["What it is","Spinal muscular atrophy: nerve cells in the spinal cord that control movement slowly die, so muscles become weak and thin. Type 1 starts from birth to 6 months, type 2 at 6–12 months, types 3–4 after early childhood or in adults."],
     ["The gene","Caused by the SMN1 gene. In most patients a part called exon 7 is missing from both copies. The similar SMN2 gene makes a little protein; more SMN2 copies usually means milder disease."],
     ["Carriers","Carriers have one changed copy and are healthy. If both parents are carriers, each pregnancy has a 1 in 4 chance of SMA. A north Indian study found about 1 in 38 healthy people were carriers. Being a carrier is not a disease."],
     ["The test","One blood sample. MLPA counts SMN1 copies: 0 = SMA confirmed, 1 = carrier, 2 = usually normal (a few people with 2 copies can still be carriers). Discuss the report with a genetic counsellor. Prenatal testing is for disease only; the baby's sex is not disclosed."],
     ["Treatment","SMA is now treatable and medicine is available in India; earlier treatment works better. Financial support may be available under the National Policy for Rare Diseases. Treatment is decided only by a specialist."]]},

 {id:"biopsy", c:"tests", t:"Biopsy & histopathology", l:"Hindi", d:"3:06",
  s:"Doctor advised a biopsy and you're scared? What it is, the types, how to prepare, the lab journey of your sample, and the biggest myth.",
  x:[["What it is","A small piece of tissue or a few cells is taken and a pathologist (lab specialist doctor) examines it under a microscope. A biopsy does not mean cancer: it also helps diagnose infection, inflammation, TB and other diseases."],
     ["Types","FNAC (thin needle, a few cells), trucut / core (thicker needle, a tissue core), ultrasound or CT guided needle biopsy, punch biopsy of skin, and surgical biopsy where a lump is removed."],
     ["Preparation","Tell the doctor all your medicines, especially blood thinners; stop a medicine only if the doctor says so. Some biopsies need an empty stomach. Mention allergy or pregnancy. Bring someone along."],
     ["After & in the lab","Usually done with numbing medicine; mild pain or a bruise is common. Contact your doctor for bleeding that doesn't stop, swelling, redness or fever. In the lab the tissue is fixed (e.g. formalin), set in wax, cut into very thin sections, stained on glass slides and examined."],
     ["Report & myth","Usually a few days to about a week; special tests like IHC may take longer. Understand the report with your doctor. Myth: biopsy spreads cancer. Fact (American Cancer Society): this is extremely rare and the benefits far outweigh the risk."]]},

 {id:"ihc", c:"tests", t:"IHC markers (immunohistochemistry)", l:"Hindi", d:"2:52",
  s:"Report says 'IHC advised'? What IHC markers are, how the brown stain works, ER/PR and HER2 in breast cancer, and how to read the report.",
  x:[["What it is","Immunohistochemistry: lab-made antibodies stick only to their matching protein in the tissue; a colour reaction turns those cells brown (positive). It shows which protein is present, so the pathologist knows what type of cell it really is."],
     ["Sample","Usually no new sample: IHC is done on the same biopsy wax block. If the biopsy was done elsewhere, the block or slides are requested from there."],
     ["Right diagnosis","Examples: TTF-1 (lung cancer), S100 (melanoma), CD20 and CD3 (B-cell vs T-cell lymphoma). The pathologist chooses the markers."],
     ["Guiding treatment","Breast cancer: ER/PR (less than 1% negative, 1–10% low positive, more than 10% positive; above 1% hormone therapy may be an option) and HER2 (0 to 3+; 3+ positive, 2+ may need FISH, 1+ or 2+ with negative FISH = HER2-low). Source: American Cancer Society."],
     ["Report","Each marker is reported positive or negative, sometimes with % and intensity. IHC can take a few extra days. No single marker decides the diagnosis; your doctor decides treatment."]]},

 {id:"btm", c:"gen", t:"Beta thalassemia mutation analysis (HBB gene)", l:"Hindi", d:"2:58",
  s:"HPLC says thalassemia carrier and the doctor advised mutation analysis? What the HBB DNA test finds, why couples need it before pregnancy, and how prenatal testing works.",
  x:[["What it is","A DNA test (on a blood sample) of the HBB gene on chromosome 11, the recipe for beta globin. HPLC screening tells whether you are a carrier; mutation analysis tells exactly which mutation."],
     ["Common in India","Many mutations exist but a few are very common. In a West Bengal hospital study (Int J Hematol 2014), IVS1-5 was found in about 47% of beta carriers, followed by codon 26 (HbE)."],
     ["How it's tested","ARMS-PCR for the common mutations; Sanger sequencing reads the gene letter by letter when needed; a separate test looks for deletions."],
     ["Why it matters","If both partners are carriers, each pregnancy has a 1 in 4 chance of thalassemia major. Testing the baby (usually by CVS at about 10–13 weeks) is possible only when both parents' mutations are known. For disease only; the baby's sex is never disclosed."],
     ["Patients & who should test","Mutation type gives a clue to severity (beta-zero: none made; beta-plus: some made; HbE with beta thal is often intermedia-like). For carrier couples before pregnancy, families with a thalassemia major child, unclear reports such as borderline HbA2, and people with thalassemia. Discuss the report with a genetic counsellor."]]},

 {id:"spep", c:"tests", t:"Protein electrophoresis (SPEP) & M-spike", l:"Hindi", d:"3:05",
  s:"Total protein high or SPEP advised? How serum proteins are separated, what an M-spike means, MGUS vs myeloma, and the next tests.",
  x:[["What it is","Serum is placed on a gel and an electric current separates the proteins into bands: albumin, alpha-1, alpha-2, beta and gamma. Gamma holds the immunoglobulins (antibodies) made by plasma cells."],
     ["When advised","Unexplained anaemia, bone pain, repeated infections, kidney problems, high calcium or high total protein; a key test when multiple myeloma is suspected."],
     ["M-spike","A tall, narrow peak: one group of plasma cells making a lot of one protein (monoclonal protein). It is not always cancer: most often it is MGUS. About 3% of people over 50 have MGUS and about 1% per year may progress, so regular follow-up matters (Mayo Clinic)."],
     ["Other patterns","Low albumin: liver or kidney disease, poor nutrition. High alpha-2: inflammation, nephrotic syndrome. Broad high gamma: chronic infection or autoimmune disease."],
     ["Next tests & prep","If an M-spike is found: immunofixation (type, e.g. IgG kappa), serum free light chains, urine protein tests, and a bone marrow test if the doctor advises. Usually just a blood sample with no special preparation; follow your lab's instructions and discuss the report with your doctor."]]},

 {id:"flc", c:"tests", t:"Serum free light chains (kappa, lambda & ratio)", l:"Hindi", d:"3:00",
  s:"Kappa, lambda and the kappa/lambda ratio explained: what free light chains are, why the ratio matters in myeloma, and how kidneys affect the result.",
  x:[["What it is","Antibodies have 2 heavy and 2 light chains; light chains are kappa or lambda. Plasma cells make a few extra light chains that float free in the blood. The test measures free kappa and free lambda."],
     ["The ratio","Kappa divided by lambda. A common reference range is 0.26 to 1.65, but ranges differ by lab and machine. If one clone of plasma cells makes one type in excess, the ratio goes up (kappa) or down (lambda)."],
     ["Why it matters","About 15% of multiple myeloma makes only light chains, and SPEP can look normal. Doctors often order it with SPEP and immunofixation. It also helps in monitoring treatment and judging risk in MGUS."],
     ["Kidneys","Free light chains are cleared by the kidneys. With weak kidneys both can rise and the ratio can go up a little; one study proposed a kidney-disease range of 0.37 to 3.1 (BMC Nephrology 2008)."],
     ["Prep & report","Just a blood sample; usually no fasting (follow your lab's instructions). The report shows kappa, lambda and the ratio. Don't judge from one report; the doctor reads it with other tests."]]},

 {id:"dexa", c:"tests", t:"DEXA scan (bone density)", l:"Hindi", d:"3:09",
  s:"Bone broke from a small fall? What a DEXA bone density scan is, who needs it, how to prepare, and how to read the T-score and Z-score.",
  x:[["What it is","Dual-Energy X-ray Absorptiometry: two low-energy X-ray beams measure bone mineral density (BMD), usually at the lower spine and hip. It is the standard test for osteoporosis (bones thin and weak inside), which grows silently; often the first sign is a fracture."],
     ["Who needs it","Women after menopause and older men; a bone broken by a minor fall; height loss of 1.5 inches (3.8 cm) or more; long-term steroid medicines; smokers. Your doctor decides."],
     ["Safety & preparation","Radiation is less than one-tenth of a chest X-ray; painless; about 10 to 30 minutes lying on a table. Eat normally, but no calcium tablets for 24 hours before; loose clothes with no metal. Tell them about pregnancy or a recent barium test or CT contrast (you may need to wait some days)."],
     ["T-score","Your bone vs a healthy young adult: -1 or higher normal; between -1 and -2.5 osteopenia (low bone mass); -2.5 or lower osteoporosis."],
     ["Z-score & tips","Z-score compares you with people of your own age; mainly used for children, young adults and women before menopause. Repeat scans at the same centre and machine. Spine arthritis or past spine surgery can affect results. Treatment is decided only by your doctor."]]},

 {id:"wes1", c:"gen", t:"WES Ep 1: Developmental delay & epilepsy", l:"Hindi", d:"2:16",
  s:"For doctors: when to consider whole exome sequencing in developmental delay, intellectual disability and early-onset epilepsy, with yields, guideline, sample needs and limits.",
  x:[["Diagnostic yield", "WES ~36% in neurodevelopmental disorders, ~53% with co-occurring conditions; chromosomal microarray ~15–20% (Srivastava et al., Genet Med 2019). Epilepsy: WES ~24% (Sheidley et al., Epilepsia, systematic review)."],
     ["Guideline", "ACMG 2021: exome/genome as a first- or second-tier test for congenital anomalies (onset before 1 year) or DD/ID (onset before 18 years)."],
     ["Sending a sample", "EDTA blood; full clinical details, previous tests, family history; trio with parents when possible; genetic counselling before and after."],
     ["Limits", "Does not reliably detect repeat expansions (e.g. Fragile X), mitochondrial DNA variants or many large deletions; VUS may be reported; non-diagnostic results can be reanalysed later."]]},

 {id:"wes2", c:"gen", t:"WES Ep 2: Prenatal exome for fetal anomalies", l:"Hindi", d:"2:04",
  s:"For doctors: prenatal exome when the scan shows an anomaly but karyotype and microarray are normal: indications, yield, trio requirements, counselling and limits.",
  x:[["When to consider", "Multiple anomalies, or one major anomaly suggesting a genetic disorder, with non-diagnostic microarray; a prior undiagnosed fetus or child with similar anomalies."],
     ["Diagnostic yield", "After normal karyotype and microarray: ~8.5% (PAGE, 610 trios) and ~10% (Petrovski, 234 trios); ~15% with multiple anomalies; skeletal anomalies higher (Lancet 2019)."],
     ["Requirements", "Trio: fetal sample by CVS or amniocentesis plus both parents; detailed ultrasound findings; pre- and post-test counselling."],
     ["Limits & counselling", "Prenatal yield is lower than postnatal (ultrasound features only); uncertain variants possible; reanalysis later can help. For disease only: fetal sex is never disclosed."]]},

 {id:"wes3", c:"gen", t:"WES Ep 3: Rapid exome in the NICU", l:"Hindi", d:"1:58",
  s:"For doctors: rapid trio exome in critically ill newborns: who to test, diagnostic yield, turnaround, impact on management and sample needs.",
  x:[["Which newborns", "Multiple congenital anomalies, unexplained seizures or severe hypotonia, metabolic crisis, unusual combination of features with negative initial tests."],
     ["Evidence", "278 ICU infants (Meng et al., JAMA Pediatrics 2017): exome diagnosis ~37% overall, ~51% with rapid trio exome; median turnaround ~13 days for rapid trio."],
     ["Impact", "About half of diagnosed infants had a change in management; families got accurate recurrence-risk counselling."],
     ["Requirements", "EDTA samples from baby and both parents; about 1–2 mL from a newborn; clinical summary and test results; family counselling. Turnaround differs by lab."]]},

 {id:"wes4", c:"gen", t:"WES Ep 4: Exome in adult specialties", l:"Hindi", d:"2:05",
  s:"For doctors: exome sequencing in adults with early-onset disease or family history: yield, kidney disease evidence, specialty uses, requirements and consent.",
  x:[["Adults", "486 adults: diagnostic yield ~17.5%, ~24% at age 18–30, ~10% over 30 (Posey et al., Genet Med 2016)."],
     ["Kidney", "3,315 CKD patients: genetic diagnosis ~9.3%; ~17% in nephropathy of unknown cause (Groopman et al., NEJM 2019)."],
     ["Other uses", "Inherited cardiomyopathy and arrhythmia, neuromuscular disorders, inherited retinal disease, early-onset unusual neurological features. A diagnosis helps treatment, prognosis and cascade testing of relatives."],
     ["Requirements & consent", "EDTA blood, detailed clinical information, 3-generation family history; sometimes a targeted panel first. Consent; decide about secondary findings; negative or uncertain results can be reviewed later."]]},

 {id:"g001", c:"gen", t:"Genetics Series Ep 1: Which genetic test, when?", l:"Hindi", d:"5:15",
  s:"For doctors: karyotype vs microarray vs gene panel vs exome, trio testing, reading the report, and a published Indian case (PGIMS Rohtak) where exome found PRRT2 self-limited infantile epilepsy. Case study PDF in the Genetics Clinical Series section.",
  x:[["Levels","Whole-chromosome changes, copy number variants (deletions/duplications), single-gene changes, and special changes such as repeat expansions. Each test sees only some of these."],
     ["Karyotype & CMA","Karyotype: chromosome number and balanced translocations; often misses 5–10 Mb changes; still used for obvious chromosomal syndromes and recurrent miscarriage. CMA: first-tier for unexplained DD/ID, autism, multiple anomalies (2010 consensus); yield ~15–20% vs ~3% for karyotype; misses balanced changes."],
     ["Panel, exome & special tests","Panel when features point to one disease group (epilepsy: 25+ genes is a first-tier option). Exome: ~20,000 genes, ~36% yield in neurodevelopmental disorders; misses repeat expansions, mitochondrial DNA, many large CNVs. Fragile X: PCR; SMA/deletions: MLPA; imprinting: methylation."],
     ["Trio & report","Trio testing helps find de novo changes. Reports use five categories (ACMG/AMP); no treatment decisions on a VUS."],
     ["Case study","6-month-old boy with seizures, normal MRI/EEG/metabolic screen, recurrence on phenytoin; exome found a PRRT2 frameshift variant: self-limited infantile epilepsy (Kadian et al., J Family Med Prim Care 2025). Seizures usually stop by about 2 years with normal development (GeneReviews)."]]},

 {id:"g002", c:"gen", t:"Genetics Series Ep 2: Reading a genetic report", l:"Hindi", d:"5:55",
  s:"For doctors: parts of a genetic report, HGVS names, the five ACMG/AMP classes, zygosity, phenotype fit, what to do with a VUS, reclassification, parental testing, secondary findings, and a published case where a VUS was re-assessed. Case study PDF in the Genetics Clinical Series section.",
  x:[["Report & HGVS","A report has indication, test, result summary, variant table (gene, variant, zygosity, inheritance, class), interpretation, recommendations and limits. c. = coding DNA change; p. = protein change."],
     ["Five classes","Pathogenic, likely pathogenic (>90% certainty), VUS, likely benign, benign (ACMG/AMP 2015). Evidence: population frequency, computational/functional data, segregation, de novo status, phenotype fit."],
     ["VUS","No treatment or predictive testing of relatives based on a VUS. Correlate with features, test parents, ask for re-analysis. In ~1.45 million people tested for hereditary cancer, 24.9% of reported VUS were reclassified, 91.2% of them to benign/likely benign (JAMA 2018)."],
     ["Parents & secondary findings","Confirmed de novo = strong evidence (PS2); assumed = moderate (PM6). Secondary findings: actionable genes on the ACMG list (80+ genes, SF v3.3 2025), reported as agreed at consent. A negative exome does not rule out genetic disease."],
     ["Case study","Girl from Mexico (IVF twin) with PDA, PFO, pulmonary hypertension, distinct features and developmental delay; karyotype 46,XX; exome found SPOP c.351G>T p.(Met117Ile) reported as VUS. Authors applied PM2, PM1, PM6, PP3 and argued likely pathogenic: Nabais Sá-de Vries syndrome type 1. No parental testing was done (Olivares-Huerta et al., Cureus 2026)."]]},
 {id:"imaging", c:"tests", t:"X-ray vs CT scan vs MRI: difference & when", l:"Hindi", d:"2:57",
  s:"How X-ray, CT and MRI work, how long they take, radiation compared with natural background, safety before MRI (pacemaker, implants, metal), pregnancy, and when doctors usually recommend each scan.",
  x:[["X-ray","Low-dose X-rays make a quick 2D picture in seconds; bone looks white. Chest X-ray ~0.1 mSv, about 10 days of natural background radiation. Used for fractures, chest infection/pneumonia/suspected TB, dental checks, joint arthritis; often the first test."],
     ["CT scan","X-rays from all around the body; a computer builds cross-section slices in a few minutes. More radiation: CT head ~1.6 mSv (~7 months of background), CT abdomen ~7.7 mSv (~2.6 years). Used in emergencies: head injury, stroke (to check for bleeding), internal injury, sudden severe belly pain, kidney stone. Contrast sometimes: tell about allergy or kidney disease."],
     ["MRI","Strong magnet and radio waves, no X-ray radiation; very fine detail of soft tissue; usually 20–40 minutes, loud. Used for brain and spinal cord problems, slip disc, knee/shoulder ligament injury, nerve problems. Tell beforehand about pacemaker, implants, metal in the body, or fear of closed spaces."],
     ["Pregnancy & choice","Tell before any scan if you are or may be pregnant; if imaging is needed, doctors often prefer MRI. The doctor chooses the scan by symptoms, urgency and safety. Avoid unnecessary repeat scans."]]},
 {id:"ana", c:"tests", t:"ANA test by IFA (antinuclear antibody)", l:"Hindi", d:"2:57",
  s:"What antinuclear antibodies are, how the HEp-2 immunofluorescence (IFA) test works, what titer and pattern mean, when doctors order it, and why a positive ANA is not always a disease.",
  x:[["What is ANA?","Antibodies the immune system mistakenly makes against the nucleus of our own cells. Found in autoimmune diseases such as lupus (SLE), Sjögren's syndrome and scleroderma."],
     ["How IFA works","Patient serum is placed on a slide of HEp-2 cells; ANA binds the nucleus; a fluorescent-tagged antibody is added and the nucleus glows green under a fluorescence microscope. The American College of Rheumatology considers HEp-2 IFA the gold standard."],
     ["Titer & pattern","Serum is diluted (1:40, 1:80, 1:160...). The highest dilution that still glows is the titer; higher titer = higher chance of disease; cut-off differs by lab. Patterns: homogeneous (often SLE), speckled (many autoimmune diseases), centromere (limited scleroderma), nucleolar (systemic sclerosis), dense fine speckled (often no autoimmune disease)."],
     ["When ordered","Joint pain with swelling, facial rash after sun exposure, mouth ulcers, fingers turning white or blue in cold, dry eyes and mouth. Usually not needed for tiredness or body ache alone."],
     ["Positive is not always disease","About 14% of people aged 12+ were ANA positive in a large US survey (NHANES 1999–2004). Infections and some medicines can also cause it. If positive, the doctor may order anti-dsDNA or an ENA profile. Usually no fasting; tell your doctor about medicines; one report alone is not a diagnosis."]]},
 {id:"g003", c:"gen", t:"Genetics Series Ep 3: Trio vs singleton testing", l:"Hindi", d:"5:15",
  s:"For doctors: singleton, duo and trio testing; what parents' samples add (de novo status, phase in recessive disease, filtering); cautions; evidence on yield and cost including Indian data; when to choose which; and a published case where singleton exome plus parental testing proved a de novo SETBP1 variant. Case study PDF in the Genetics Clinical Series section.",
  x:[["Why parents help","De novo: present in the patient, absent in both parents; confirmed de novo is strong ACMG evidence (PS2). Phase: two variants in one gene, in trans (compound heterozygous) or in cis. Filtering: fewer variants to review, faster reports, often fewer VUS."],
     ["Cautions","A variant in a healthy parent is not always harmless: reduced penetrance, variable expressivity, parental mosaicism. Consent covers possible unexpected family-relationship findings."],
     ["Evidence","Tan et al. 2019 (30 children): singleton exome 36.7% vs trio 40.0%; trio nearly doubled total cost; singleton first with reflex to trio was cost-saving. Kiel study (448 patients, genome): trio 36.8% vs singleton 30.4%. Mumbai (137 children with autism, trio exome): 16.1% P/LP; syndromic 35% vs non-syndromic 8.2%; 91.3% de novo."],
     ["Which to choose","Trio for critically ill newborns, severe developmental delay or multiple anomalies, and prenatal anomalies. Singleton when cost is limited or parents are unavailable, followed by targeted parental testing when needed."],
     ["Case study","5-year-old girl with motor and speech delay; normal MRI, EMG and metabolic screen. Singleton exome: SETBP1 c.1630C>T p.(Arg544Ter). Sanger in parents and sister: absent, so de novo; classified pathogenic; diagnosis MRD29 (Pan et al., Front Genet 2025)."]]},
 {id:"fcp", c:"tests", t:"Fecal calprotectin (IBS or IBD?)", l:"Hindi", d:"2:53",
  s:"What fecal calprotectin is, how it helps tell IBS from IBD, when doctors order it, how to read the result, other causes of a raised value, how to give the stool sample, and warning signs that need a doctor straight away.",
  x:[["What it is","A protein from neutrophils (white blood cells). When the gut is inflamed, neutrophils gather in the gut wall and calprotectin passes into the stool; more inflammation means more calprotectin."],
     ["IBS vs IBD","IBS: sensitive gut without inflammation, calprotectin usually normal. IBD (Crohn's disease, ulcerative colitis): real inflammation, calprotectin raised. Helps decide who needs a colonoscopy; also used to monitor known IBD."],
     ["Result","Below 50 µg/g is usually normal; borderline values may be repeated after a few weeks; high values point to gut inflammation. Ranges differ by lab (e.g. Labcorp: <50 normal, 50–120 borderline, >120 abnormal)."],
     ["Other causes","Gut infection, NSAID painkillers, PPI acidity medicines, coeliac disease, diverticular disease, colon polyps or cancer. Children under 2 normally have slightly higher values."],
     ["Sample & warning signs","Small amount of stool in a clean container, no urine or water, outside kept clean, delivered within the lab's time limit. Blood in stool, weight loss, anaemia or a new change in bowel habit at an older age: see a doctor promptly."]]},
 {id:"g004", c:"gen", t:"Genetics Series Ep 4: Inheritance patterns & the pedigree", l:"Hindi", d:"5:13",
  s:"For doctors: the 3-generation pedigree, standard symbols, what to ask, autosomal dominant and recessive, X-linked and mitochondrial patterns, why the pedigree matters, and a published Mumbai case where the pedigree pointed to recessive leptin receptor deficiency. Case study PDF in the Genetics Clinical Series section.",
  x:[["Pedigree","Three generations: patient, siblings and children; parents, uncles, aunts and cousins; grandparents. Symbols: square male, circle female, filled affected, central dot carrier, diagonal line deceased, arrow proband, double line consanguinity. Ask age at onset, cause and age of death, miscarriages, stillbirths, infant deaths, consanguinity."],
     ["Dominant & recessive","Autosomal dominant: every generation, both sexes, father-to-son possible, 50% risk to each child; watch for reduced penetrance, variable expressivity, de novo. Autosomal recessive: affected siblings, healthy carrier parents; 25% affected, 50% carrier, 25% neither; consanguinity increases the chance."],
     ["X-linked & mitochondrial","X-linked recessive: mostly males, through carrier mothers, never father to son; carrier mother: each son 50% affected, each daughter 50% carrier (e.g. DMD, haemophilia). X-linked dominant: affected father, all daughters affected, no sons. Mitochondrial: only from the mother."],
     ["Case study","Mumbai: 8-year-old girl with severe early obesity; consanguineous healthy parents; affected younger brother and an affected elder brother who died at ~1.5 years: recessive pattern. Exome: homozygous LEPR variant; parents carriers; congenital leptin receptor deficiency (Patil et al., J Pediatr Endocrinol Diabetes 2023)."]]},
 {id:"brca", c:"tests", t:"BRCA1/BRCA2 test (hereditary cancer)", l:"Hindi", d:"2:55",
  s:"What BRCA genes do, how much a harmful change raises breast, ovarian and other cancer risk, who should consider testing, the three possible results, what happens if positive, and why the result matters for the whole family.",
  x:[["What BRCA genes do","BRCA1 and BRCA2 repair DNA damage and protect against cancer. A harmful change weakens this protection. It can come from the mother or father; each child has a 50% chance of inheriting it."],
     ["Risk","Lifetime breast cancer: about 13% in women generally vs more than 60% with a harmful BRCA change. Ovarian: about 1% vs 39–58% (BRCA1) and 13–29% (BRCA2). Men: higher risk of breast, prostate and pancreatic cancer (US National Cancer Institute)."],
     ["Who should consider testing","Breast cancer at 50 or younger, ovarian cancer at any age, male breast cancer, pancreatic or advanced prostate cancer, or a known BRCA change in the family. Decide with a doctor or genetic counsellor; usually not done under 18. Blood or saliva sample, with counselling before and after."],
     ["Results & next steps","Positive: higher risk, not certainty. Negative: no harmful change found, usual risk remains. VUS: no big decisions on it. If positive: earlier and more frequent screening (e.g. mammography plus MRI), preventive options discussed with a specialist, and it can guide cancer treatment. Relatives can be tested for the same change."]]},
 {id:"sero", c:"tests", t:"Serology profile (HIV, HBsAg, HCV, VDRL)", l:"Hindi", d:"2:55",
  s:"What a serology profile checks (HIV 1&2, hepatitis B, hepatitis C, syphilis), why it is done before surgery, in pregnancy and after needle-stick injury, what reactive and non-reactive mean, window period, confirmation and confidentiality.",
  x:[["What is checked","HIV 1 & 2, hepatitis B (HBsAg), hepatitis C (anti-HCV) and syphilis (VDRL or RPR). Blood test, no fasting. Report says reactive or non-reactive."],
     ["Why","Before surgery, endoscopy and dialysis (protects patient and health workers), in pregnancy (protects the baby), and after a needle-stick injury."],
     ["HIV","Lab test checks antibody and antigen; it can usually detect infection 18–45 days after exposure (HIV.gov), so an early test may need repeating. Reactive results need confirmatory tests. Done with consent; result confidential."],
     ["Hepatitis B & C","HBsAg present = current hepatitis B infection; more than 6 months = chronic; vaccine protects family. Anti-HCV = infection now or in the past; HCV RNA confirms current infection; today's medicines cure over 95% (WHO)."],
     ["Syphilis & reminders","VDRL/RPR is a screening test; can be falsely positive (pregnancy, TB, autoimmune disease, some viral infections); confirmed with TPHA; treatable with penicillin. A reactive screen is not a final diagnosis. Keep the report confidential."]]},
 {id:"anca", c:"tests", t:"ANCA test (c-ANCA / p-ANCA)", l:"Hindi", d:"2:55",
  s:"What ANCA is, the c-ANCA and p-ANCA patterns, PR3 and MPO tests, which vasculitis they point to, when doctors order the test and how to read the report.",
  x:[["What is ANCA?","Anti-neutrophil cytoplasmic antibodies: made by mistake against neutrophils (white blood cells). Linked to vasculitis, i.e. inflammation of blood vessels."],
     ["c-ANCA vs p-ANCA","Under the fluorescence microscope, c-ANCA shows cytoplasmic glow (usually PR3 antibody); p-ANCA shows a ring around the nucleus (usually MPO antibody). The 2017 international consensus recommends PR3 and MPO immunoassays as the first test, adding the microscope test (IIF) when needed."],
     ["Which disease","PR3/c-ANCA: often GPA (nose, lungs, kidneys). MPO/p-ANCA: often microscopic polyangiitis and EGPA. p-ANCA can also appear in some other diseases and with some medicines."],
     ["When ordered","Long-standing sinus problems, nasal crusting, nosebleeds, blood in cough, blood or protein in urine with rising creatinine, skin rash, numbness, unexplained fever and weight loss, asthma with high eosinophils."],
     ["Report","Positive alone is not a diagnosis; negative does not fully rule out vasculitis (Mayo Clinic Laboratories). Doctor decides with symptoms, other tests and sometimes a biopsy. Kidney vasculitis can progress fast, so early diagnosis matters. Blood sample, no fasting."]]},
 {id:"g005", c:"gen", t:"Genetics Series Ep 5: Genetic counselling & consent", l:"Hindi", d:"4:56",
  s:"For doctors: what genetic counselling is, pre-test counselling, consent decisions (secondary findings, data storage, sharing), family implications, testing children, prenatal testing under PCPNDT, post-test counselling, privacy, and a published Indian case. Case study PDF in the Genetics Clinical Series section.",
  x:[["Pre-test & consent","Why the test, what it can and cannot find, possible results (positive, negative, VUS), time and cost; consent decisions on secondary findings, sample/data storage for re-analysis and report sharing. Non-directive: the family decides."],
     ["Family, children, prenatal","Results can show risk for relatives; trio tests can reveal unexpected family-relationship information. Predictive testing of children for adult-onset conditions with no childhood intervention is usually deferred until adulthood (ASHG 2015). Prenatal: PCPNDT written consent, disease only, fetal sex never disclosed."],
     ["Post-test & privacy","Explain the report simply, management and referrals, recurrence risk, cascade testing, emotional support; no major decisions on a VUS. Keep genetic reports confidential (ICMR National Ethical Guidelines)."],
     ["Case study","Two siblings (Pune/Delhi) with lamellar ichthyosis: homozygous TGM1 variant, carrier parents, plus a paternally inherited 22q12 duplication of unclear relevance. The mother was pregnant again (25% risk) and prenatal testing was planned (Gupta et al., F1000Research 2015)."]]},
 {id:"story", c:"bio", t:"From Protein to Cell: the full story", l:"Hindi", d:"4:09",
  s:"Seven chapters in one video: protein, gene, DNA, histones, chromosome, nucleus and cell.",
  x:[["Chapters","Protein · Gene · DNA · Histones · Chromosome · Nucleus · Cell"],
     ["Big picture","Recipes for proteins are in genes, genes are in DNA, DNA wraps into chromosomes inside the nucleus of every cell."],
     ["Lab link","Albumin (protein), HPLC (haemoglobin), karyotype (chromosomes), Pap smear (cells), CBC (blood cells)."]]},
 {id:"cell", c:"bio", t:"What is a Cell?", l:"Hindi", d:"2:03",
  s:"You are made of about 30 lakh crore cells. Each one is a tiny factory.",
  x:[["Parts","Membrane = security wall · Nucleus = head office · Mitochondria = powerhouse · Ribosomes = protein workers"],
     ["Lifespan","Skin cells 2–4 weeks · Red blood cells about 120 days · Many nerve cells a whole lifetime"],
     ["Lab link","CBC counts blood cells; Pap smear and FNAC look at cells under the microscope."]]},
 {id:"nucleus", c:"bio", t:"What is the Nucleus?", l:"Hindi", d:"1:44",
  s:"Every cell has a boss, except red blood cells.",
  x:[["Inside","A wall with gates (nuclear pores), DNA files, and the nucleolus."],
     ["Fun fact","Red blood cells have no nucleus, which leaves more room for haemoglobin."],
     ["Lab link","WBC types are told apart by nucleus shape (the CBC differential)."]]},
 {id:"chromosome", c:"bio", t:"What is a Chromosome?", l:"Hindi", d:"2:20",
  s:"46 chromosomes in 23 pairs, and the truth about who decides a baby's sex.",
  x:[["Basics","46 chromosomes in every cell: 23 from mother, 23 from father."],
     ["Myth busted","The father's X or Y decides whether a baby is a boy or girl, not the mother. Sex determination before birth is illegal in India."],
     ["Tests","Karyotyping; double marker or NIPT in pregnancy, as your doctor advises."]]},
 {id:"dna", c:"bio", t:"What is DNA?", l:"Hindi", d:"1:57",
  s:"A 4-letter code, about 3 billion letters long, in every cell.",
  x:[["The code","Four letters: A pairs with T, G pairs with C."],
     ["Fun fact","You share about 99.9% of your DNA with every human. DNA from one cell is about 2 metres long."],
     ["Tests","Genetic disease tests like thalassaemia, some cancer risk genes, paternity, and forensics."]]},
 {id:"gene", c:"bio", t:"What is a Gene?", l:"Hindi", d:"1:47",
  s:"DNA is the cookbook, a gene is one recipe, a protein is the dish.",
  x:[["Basics","About 20,000 genes, each in two copies: one from mother, one from father."],
     ["Carriers","Two healthy thalassaemia carriers have a 1 in 4 chance, each pregnancy, of a child with thalassaemia major."],
     ["Lifestyle","Family history raises risk, but healthy habits can change the story."]]},
 {id:"histones", c:"bio", t:"What are Histones?", l:"Hindi", d:"1:59",
  s:"Protein spools that pack 2 metres of DNA into a tiny cell and switch genes on and off.",
  x:[["Basics","Eight histones make one core. DNA wraps around it to form a nucleosome, like beads on a string."],
     ["Gene switch","Tight wrap = gene off; loose wrap = gene on. This is epigenetics."],
     ["Don't confuse","Histones are not antihistamines. Antihistamines are allergy medicines."]]},

 {id:"thyroid", c:"daily", t:"Thyroid test (TSH, T3, T4)", l:"Hindi", d:"2:24",
  s:"Wednesday tips, 7 Oct 2026. Always tired, weight going up, hair falling? Check your thyroid.",
  x:[["What it checks","TSH (the signal from the brain) and T3, T4 (the thyroid hormones). TSH high usually means a slow thyroid; TSH low usually means a fast thyroid."],
     ["Symptoms","Slow (hypo): tiredness, weight gain, feeling cold, hair fall, constipation. Fast (hyper): weight loss, fast heartbeat, sweating, shaky hands, anxiety."],
     ["Who should test","Women over 35, before or during pregnancy, after delivery, thyroid in the family, diabetes, PCOD or irregular periods. For newborns, ask your doctor about thyroid screening."],
     ["Preparation","Usually no fasting. Morning sample is best. On a thyroid tablet, give the sample before the dose as your doctor says. Tell your doctor if you take biotin."],
     ["Good to know","About 1 in 10 adults in India has hypothyroidism. Never stop or change your thyroid tablet on your own."]]},
 {id:"alz", c:"tests", t:"Alzheimer's & memory loss tests", l:"Hindi", d:"3:24",
  s:"Forgetting the way home? How doctors check for Alzheimer's, and which causes can be treated.",
  x:[["Is there one test?","No single test. Doctors (usually a neurologist or psychiatrist) combine memory tests such as MMSE, blood tests and a brain scan."],
     ["Warning signs","Forgetting recent events, asking the same question again, getting lost in familiar places, trouble with money or daily tasks, mood or behaviour changes."],
     ["Blood tests","Look for treatable causes: vitamin B12, thyroid, sugar, CBC (anaemia), kidney and liver tests. Treating these can improve memory."],
     ["Brain scan","MRI or CT rules out stroke, tumour or fluid and can show brain shrinkage. Sometimes PET or spinal fluid tests are used."],
     ["New blood test","pTau217 / Beta-Amyloid 1-42 ratio (plasma): a blood sample, report in about 48 hours, for adults 50+ with signs of memory decline. Positive = high chance of Alzheimer's-related amyloid changes; grey zone = more tests may be needed; negative = very low chance. Not a screening test and not a diagnosis on its own; your doctor reads it with other tests."],
     ["In India","About 7.4% of people over 60 (around 88 lakh) have dementia (LASI-DAD, 2023). Up to 45% of dementia may be prevented or delayed (Lancet Commission, 2024)."]]},
 {id:"uric", c:"daily", t:"Uric acid test: gout & joint pain", l:"Hindi", d:"3:04",
  s:"Saturday tips, 10 Oct 2026. Sudden pain and swelling in the big toe? What uric acid is, why it rises and how to read the test.",
  x:[["What it is","Uric acid is a waste made when purines (found in our cells and some foods) break down. Most of it leaves the body through the kidneys in urine."],
     ["Why it matters","If the body makes too much or the kidneys remove too little, the level rises. Needle-like crystals can form in joints (gout), and some people get kidney stones."],
     ["What can raise it","Red and organ meat, some seafood, alcohol (especially beer), sugary soft drinks, extra weight, kidney disease, some medicines, and gout in the family."],
     ["The test","A simple blood test; some labs ask for a few hours of fasting, so follow your lab's instructions. Avoid alcohol before the test and tell your doctor about your medicines. A 24-hour urine uric acid is sometimes done, mainly for kidney stones."],
     ["Reading the result","Usually about 3.5 to 7 mg/dL (approximately), a little lower in women; ranges vary by lab. Uric acid can be normal during a gout attack, and many people with high uric acid never get gout. Whether medicine is needed is decided by your doctor."]]},
 {id:"sugar", c:"daily", t:"Blood sugar: fasting, PP & GTT", l:"Hindi", d:"2:49",
  s:"Friday tips, 9 Oct 2026. Thirsty, passing urine often, slow healing? The 3 main sugar tests and what the numbers mean.",
  x:[["Fasting (FBS)","No food for at least 8 hours; plain water is fine. Below 100 mg/dL normal, 100–125 prediabetes, 126 or more may be diabetes (ADA criteria)."],
     ["PP (post-meal)","Blood taken 2 hours from the start of your usual meal. Usually below 140 mg/dL is considered normal; lab ranges vary slightly."],
     ["GTT (75 g)","Fasting sample, then 75 g glucose drink and a sample at 2 hours. Below 140 normal, 140–199 prediabetes, 200 or more diabetes. Don't eat and sit quietly during the test."],
     ["In pregnancy","India uses the DIPSI test: 75 g glucose, fasting not needed; 2-hour value of 140 mg/dL or more means gestational diabetes. First visit and again at 24–28 weeks."],
     ["Who should test","Everyone above 30, family history of diabetes, overweight or high BP, PCOD, or thirst, frequent urination and tiredness. Doctors confirm with a repeat test."]]},
 {id:"ecg", c:"daily", t:"ECG test: the heart tracing", l:"Hindi", d:"3:02",
  s:"Thursday tips, 8 Oct 2026. Chest pain, racing heart or dizziness? What an ECG shows and how to prepare.",
  x:[["What it is","An ECG (electrocardiogram) records the heart's tiny electrical signals as waves. Painless, takes only a few minutes, and no current goes into the body."],
     ["When doctors advise it","Chest pain or heaviness, fast or irregular heartbeat, dizziness or fainting, breathlessness, suspected heart attack. Also before an operation, after a past heart problem, with a strong family history of heart disease, or to check a pacemaker."],
     ["Preparation","Wear a top that opens easily. No cream, oil or powder on the chest. No exercise or cold water just before the test. Tell the staff about your medicines. Lie still and relax."],
     ["Reading the report","A resting heart rate of about 60 to 100 per minute with a regular rhythm is usually considered normal. An ECG records only a few seconds, so a normal ECG does not rule out every heart problem; your doctor may advise Holter, TMT or ECHO and reads the ECG with your symptoms."],
     ["Heart attack warning signs","Chest pain or pressure spreading to the arm, jaw or back, with sweating, breathlessness or uneasiness. Women, the elderly and people with diabetes may have no chest pain. Don't wait: call an ambulance or go to the nearest hospital."]]},
 {id:"esrcrp", c:"daily", t:"ESR & CRP: inflammation tests", l:"Hindi", d:"3:16",
  s:"Sunday tips, 11 Oct 2026. Fever that won't go or joint pain? What ESR and CRP show, how they differ and how to read the report.",
  x:[["What they are","Two common blood tests that act like smoke alarms for inflammation (the body's response to infection, injury or disease). They show that inflammation is present, not where it is or what is causing it."],
     ["ESR vs CRP","ESR measures how many mm red blood cells settle in a tall tube in 1 hour (mm/hr). CRP is a protein made by the liver; it rises within hours and falls quickly as things settle, while ESR rises over 1–2 days and may take weeks to come down."],
     ["When doctors order them","Long unexplained fever, joint pain, swelling or stiffness, muscle pain, suspected infection, and to see whether treatment is working in arthritis and similar conditions."],
     ["The test","A simple blood test; usually no fasting is needed, but follow your lab's instructions and tell your doctor about your medicines. hs-CRP is a more sensitive CRP test that is sometimes used to estimate heart disease risk."],
     ["Reading the result","ESR is approximately up to 15 mm/hr in men and 20 mm/hr in women under 50, a little higher after 50. CRP is very low in most healthy people; labs report it in mg/L or mg/dL (10 mg/L = 1 mg/dL). Ranges vary by lab. Age, pregnancy and anaemia can raise ESR; obesity and smoking can raise CRP mildly. A high value has many causes and a normal one doesn't rule out every disease: your doctor reads it with your symptoms and other tests."]]},
 {id:"iron", c:"daily", t:"Iron studies & Ferritin", l:"Hindi", d:"2:56",
  s:"Monday tips, 12 Oct 2026. Always tired or pale? What iron studies and ferritin show, who may need them and how to read the report.",
  x:[["What they are","A group of blood tests: serum iron (iron in the blood right now), TIBC / transferrin (the protein 'taxis' that carry iron), transferrin saturation (how full those taxis are) and ferritin (iron stored in the body). Iron is needed to make haemoglobin, which carries oxygen."],
     ["Why it matters","In India's NFHS-5 survey (2019–21), about 57% of women aged 15–49 and about 67% of children aged 6–59 months had anaemia; low iron is one common cause. Signs include tiredness, weakness, pale skin, breathlessness, fast heartbeat, headache, cold hands and feet, brittle nails and cravings for ice or clay."],
     ["Who may need it","As your doctor advises: anaemia or small red cells on a CBC, heavy periods, pregnancy, poor diet (some children and vegetarians), frequent blood donors, stomach or gut disease, and people who get many blood transfusions (e.g. thalassaemia), where MRI may also be used to check liver and heart iron."],
     ["Preparation","Serum iron is highest in the morning and changes through the day, so a morning sample is better; many labs ask for about 8 hours of fasting. Ferritin alone usually needs no fasting. Follow your lab's instructions, and if you take iron tablets or injections, tell your doctor before the test."],
     ["Reading the result","Low iron usually shows low ferritin, low serum iron, high TIBC and low saturation; iron overload shows high ferritin and high saturation. WHO: in healthy people aged 5+, ferritin below about 15 ng/mL means iron deficiency. Transferrin saturation is approximately 20–50% in men and 15–45% in women; ranges vary by lab. Infection, inflammation or liver disease can raise ferritin, so it may look normal even when iron is low. Not every anaemia is low iron (thalassaemia trait also gives small red cells and does not need iron), and too much iron can harm organs: take iron only as your doctor advises."]]},
 {id:"calcium", c:"daily", t:"Calcium & Phosphorus tests", l:"Hindi", d:"3:03",
  s:"Tuesday tips, 13 Oct 2026. Cramps, tingling or kidney stones? What calcium and phosphorus tests show, who may need them and how to read the report.",
  x:[["What they are","Blood tests for two bone minerals. About 98–99% of the body's calcium and about 85% of its phosphorus are stored in bones and teeth; the small amount in blood is vital for muscles and nerves. Parathyroid hormone, vitamin D and the kidneys keep the levels in balance, and when calcium goes up phosphorus often goes down, so they are usually tested together."],
     ["Signs of imbalance","Low calcium may cause tingling in the fingers, toes or around the lips, muscle cramps and twitching. High calcium often causes no symptoms at first; later there may be thirst, passing urine often, tiredness, constipation, nausea and kidney stones. These signs have many causes, so only a test can tell."],
     ["Common causes","High calcium: most often an overactive parathyroid gland or some cancers. Low calcium: low vitamin D, underactive parathyroid, kidney disease, low albumin or low magnesium. High phosphorus: often a kidney problem. Low phosphorus: low vitamin D, very poor nutrition, alcohol or an overactive parathyroid. Your doctor finds the cause, often with PTH and vitamin D tests."],
     ["Who may need it","As your doctor advises: routine check-ups (often part of a blood panel), cramps or tingling, kidney disease, parathyroid or bone problems, repeated kidney stones (urine calcium-creatinine ratio or 24-hour urine calcium), and people on medicines that affect calcium. A calcium test alone usually needs no special preparation; with other tests a few hours of fasting may be asked. Tell your doctor about calcium, vitamin D, antacids, water pills or thyroid medicine, and never stop a medicine on your own."],
     ["Reading the result","Approximate adult ranges: total calcium 8.5–10.2 mg/dL, ionised calcium 4.5–5.6 mg/dL, phosphorus 2.8–4.5 mg/dL (higher in children because bones are growing). Ranges vary by lab. About half of blood calcium is bound to albumin, so low albumin can make total calcium look low; the doctor may order ionised calcium. Normal blood calcium does not mean strong bones: the body takes calcium from bones to keep the blood level steady, and bone strength is checked with a bone density (DEXA) scan. A 'calcium score' is a CT scan of the heart arteries, not a blood test."]]},
 {id:"fever", c:"daily", t:"Dengue, Malaria or Typhoid?", l:"Hindi", d:"1:49",
  s:"Monday tips, 5 Oct 2026. Same fever, different test.",
  x:[["Dengue","High fever, eye and body pain, rash. Test: NS1 (days 1–5), IgM (after day 5), CBC for platelets."],
     ["Malaria","Fever with chills that comes and goes. Test: rapid antigen test or blood smear."],
     ["Typhoid","Slowly rising fever, stomach upset. Test: blood culture as your doctor advises."],
     ["Fever rules","Test within 1–3 days, no antibiotics or painkillers on your own, plenty of water and ORS."]]},
 {id:"thal", c:"daily", t:"Thalassaemia: test before marriage", l:"Hindi", d:"2:24",
  s:"Tuesday tips, 6 Oct 2026. One blood test can protect your future child.",
  x:[["Carrier vs major","Carriers are usually healthy. Thalassaemia major needs blood transfusions every 2–4 weeks for life."],
     ["The risk","If both parents are carriers, each pregnancy has a 1 in 4 chance of thalassaemia major."],
     ["The test","CBC gives the first clue; HPLC confirms. Once in a lifetime, ideally before marriage or pregnancy."],
     ["Myth","Not all anaemia needs iron. Take iron only as your doctor advises."]]}
];

